import ChannelIcon from '@/components/icons/ChannelIcon.vue';
const CHANNEL_OPTIONS = [{
  value: 'telegram',
  label: 'TG'
}, {
  value: 'cfr2',
  label: 'R2'
}, {
  value: 's3',
  label: 'S3'
}, {
  value: 'discord',
  label: 'DC'
}, {
  value: 'huggingface',
  label: 'HF'
}, {
  value: 'webdav',
  label: 'WD'
}];
export default {
  name: 'UploadSettingsDialog',
  components: {
    ChannelIcon
  },
  data() {
    return {
      channelVisibility: 'configured'
    };
  },
  methods: {
    hasConfiguredChannels(channelType) {
      const channels = this.availableChannels[channelType];
      return Array.isArray(channels) && channels.length > 0;
    },
    handleChannelVisibilityChange(visibility) {
      if (visibility !== 'configured') {
        return;
      }
      this.ensureConfiguredChannelSelected();
    },
    ensureConfiguredChannelSelected() {
      if (this.channelVisibility !== 'configured' || this.hasConfiguredChannels(this.uploadChannel)) {
        return;
      }
      const firstConfiguredChannel = this.visibleChannelOptions[0];
      if (firstConfiguredChannel) {
        this.$emit('update:uploadChannel', firstConfiguredChannel.value);
      }
    },
    handleUploadFolderInput(val) {
      // 自动补全前导 /
      if (val && !val.startsWith('/')) {
        val = '/' + val;
      }
      this.$emit('update:uploadFolder', val);
    }
  },
  props: {
    modelValue: {
      type: Boolean,
      default: false
    },
    uploadChannel: {
      type: String,
      default: 'telegram'
    },
    channelName: {
      type: String,
      default: ''
    },
    availableChannels: {
      type: Object,
      default: () => ({})
    },
    currentChannelList: {
      type: Array,
      default: () => []
    },
    uploadFolder: {
      type: String,
      default: ''
    },
    autoRetry: {
      type: Boolean,
      default: true
    },
    uploadNameType: {
      type: String,
      default: 'default'
    },
    convertToWebp: {
      type: Boolean,
      default: true
    },
    customerCompress: {
      type: Boolean,
      default: true
    },
    compressBar: {
      type: Number,
      default: 1
    },
    compressQuality: {
      type: Number,
      default: 0.8
    },
    serverCompress: {
      type: Boolean,
      default: true
    },
    videoCompress: {
      type: Boolean,
      default: true
    },
    videoCompressRate: {
      type: Number,
      default: 75
    },
    videoCompressTargetSize: {
      type: Number,
      default: 0
    },
    videoCompressBar: {
      type: Number,
      default: 5
    },
    videoCompressMaxInput: {
      type: Number,
      default: 100
    }
  },
  emits: ['update:modelValue', 'update:uploadChannel', 'update:channelName', 'update:uploadFolder', 'update:autoRetry', 'update:uploadNameType', 'update:convertToWebp', 'update:customerCompress', 'update:compressBar', 'update:compressQuality', 'update:serverCompress', 'update:videoCompress', 'update:videoCompressRate', 'update:videoCompressTargetSize', 'update:videoCompressBar', 'update:videoCompressMaxInput'],
  watch: {
    availableChannels: {
      handler() {
        this.ensureConfiguredChannelSelected();
      },
      deep: true
    }
  },
  computed: {
    visible: {
      get() {
        return this.modelValue;
      },
      set(val) {
        this.$emit('update:modelValue', val);
      }
    },
    visibleChannelOptions() {
      if (this.channelVisibility === 'all') {
        return CHANNEL_OPTIONS;
      }
      return CHANNEL_OPTIONS.filter(channel => this.hasConfiguredChannels(channel.value));
    },
    dialogWidth() {
      return window.innerWidth > 768 ? '50%' : '90%';
    }
  }
};