/**
 * 浏览器本地视频压缩（MediaRecorder + canvas.captureStream）。
 *
 * 完全在客户端重新编码，不依赖服务端 ffmpeg，因此 Cloudflare Workers / Pages
 * 部署也能压缩视频。服务端转码能力仍然保留给直接调用 /upload API 的场景。
 *
 * 限制（会在结果里给出明确 reason，调用方据此提示用户并按原文件上传）：
 * - 需要浏览器支持 MediaRecorder 与 canvas.captureStream，且能解码源视频；
 * - 录制是实时的，耗时约等于视频时长（上传的都是小文件，不为此预设跳过门槛）；
 * - mov / mkv / avi 等容器取决于浏览器解码能力，无法解码时返回 unsupported；
 * - 仅保留超时与极大时长上限，防止异常文件让录制永久挂起。
 */
import { resolveLivePhotoVideoBitrate } from '@/utils/upload/livePhotoSettings';

const MB = 1024 * 1024;
const AUDIO_BITRATE = 96_000;

const OUTPUT_TYPES = [
    'video/mp4;codecs="avc1.42E01E,mp4a.40.2"',
    'video/mp4;codecs="avc1.42E01E"',
    'video/mp4',
    'video/webm;codecs=vp9,opus',
    'video/webm;codecs=vp8,opus',
    'video/webm'
];

export const BROWSER_VIDEO_DEFAULTS = Object.freeze({
    enabled: true,
    rate: 75,              // 压缩率 0-100，越大体积越小
    targetSize: 0,         // 期望大小 MB，0 表示只按压缩率
    maxEdge: 1280,         // 输出视频最大边长 px
    // 上传的都是小文件，不为性能预设门槛；仅保留一个极大的安全上限防止异常输入。
    maxDurationSec: 3600,
    minInputMB: 0,
});

function clamp(value, fallback, min, max) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? Math.min(max, Math.max(min, parsed)) : fallback;
}

export function clampBrowserVideoConfig(raw = {}) {
    const enabled = raw.enabled === undefined || raw.enabled === null
        ? BROWSER_VIDEO_DEFAULTS.enabled
        : (raw.enabled === true || raw.enabled === 'true');
    return {
        enabled,
        rate: clamp(raw.rate, BROWSER_VIDEO_DEFAULTS.rate, 0, 100),
        targetSize: clamp(raw.targetSize, BROWSER_VIDEO_DEFAULTS.targetSize, 0, 1024),
        maxEdge: clamp(raw.maxEdge, BROWSER_VIDEO_DEFAULTS.maxEdge, 360, 4096),
        maxDurationSec: clamp(raw.maxDurationSec, BROWSER_VIDEO_DEFAULTS.maxDurationSec, 5, 3600),
        minInputMB: clamp(raw.minInputMB, BROWSER_VIDEO_DEFAULTS.minInputMB, 0, 1024),
    };
}

function getSupportedMimeType() {
    if (typeof MediaRecorder === 'undefined') return '';
    return OUTPUT_TYPES.find(type => MediaRecorder.isTypeSupported(type)) || '';
}

function getOutputName(file, mimeType) {
    const extension = mimeType.includes('mp4') ? '.mp4' : '.webm';
    const baseName = String(file?.name || 'video').replace(/\.[^.]+$/, '');
    return `${baseName}${extension}`;
}

function waitForMedia(video) {
    return new Promise((resolve, reject) => {
        const cleanup = () => {
            video.removeEventListener('loadeddata', onLoaded);
            video.removeEventListener('error', onError);
        };
        const onLoaded = () => {
            cleanup();
            resolve();
        };
        const onError = () => {
            cleanup();
            reject(new Error('The browser could not decode this video'));
        };
        video.addEventListener('loadeddata', onLoaded, { once: true });
        video.addEventListener('error', onError, { once: true });
        if (video.readyState >= HTMLMediaElement.HAVE_CURRENT_DATA) onLoaded();
    });
}

/**
 * @returns {{file: File, compressed: boolean, reason: string, before?: number, after?: number}}
 * reason: compressed | disabled | too-small | unsupported | too-long | no-gain | timeout | failed
 */
export async function compressVideoInBrowser(file, options = BROWSER_VIDEO_DEFAULTS) {
    const settings = clampBrowserVideoConfig(options);
    const passthrough = (reason, extra = {}) => ({ file, compressed: false, reason, ...extra });
    if (!settings.enabled) return passthrough('disabled');
    if (!file || file.size < settings.minInputMB * MB) return passthrough('too-small');

    const mimeType = getSupportedMimeType();
    if (!mimeType || typeof HTMLCanvasElement === 'undefined' || !HTMLCanvasElement.prototype.captureStream) {
        return passthrough('unsupported');
    }

    const sourceUrl = URL.createObjectURL(file);
    const video = document.createElement('video');
    video.preload = 'auto';
    video.playsInline = true;
    video.src = sourceUrl;

    let outputStream;
    let audioContext;
    let frameRequest = 0;
    let recorder;
    let timeoutId;

    try {
        try {
            await waitForMedia(video);
        } catch (error) {
            return passthrough('unsupported');
        }

        const width = video.videoWidth;
        const height = video.videoHeight;
        const duration = video.duration;
        if (!width || !height || !Number.isFinite(duration) || duration <= 0) {
            return passthrough('unsupported');
        }
        if (duration > settings.maxDurationSec) {
            return passthrough('too-long', { duration });
        }

        const scale = Math.min(1, settings.maxEdge / Math.max(width, height));
        const outputWidth = Math.max(2, Math.round(width * scale / 2) * 2);
        const outputHeight = Math.max(2, Math.round(height * scale / 2) * 2);
        const canvas = document.createElement('canvas');
        canvas.width = outputWidth;
        canvas.height = outputHeight;
        const context = canvas.getContext('2d', { alpha: false });
        if (!context) return passthrough('unsupported');

        outputStream = canvas.captureStream(24);

        // 把源音频接到录制流，同时通过 gain=0 静音外放。
        if (typeof AudioContext !== 'undefined') {
            try {
                audioContext = new AudioContext();
                const audioSource = audioContext.createMediaElementSource(video);
                const audioDestination = audioContext.createMediaStreamDestination();
                const silentOutput = audioContext.createGain();
                silentOutput.gain.value = 0;
                audioSource.connect(audioDestination);
                audioSource.connect(silentOutput);
                silentOutput.connect(audioContext.destination);
                await audioContext.resume();
                audioDestination.stream.getAudioTracks().forEach(track => outputStream.addTrack(track));
            } catch (error) {
                console.warn('Video audio could not be included in the compressed clip:', error);
            }
        }

        recorder = new MediaRecorder(outputStream, {
            mimeType,
            videoBitsPerSecond: resolveLivePhotoVideoBitrate(settings, duration),
            audioBitsPerSecond: AUDIO_BITRATE,
        });
        const chunks = [];
        const recordingDone = new Promise((resolve, reject) => {
            recorder.addEventListener('dataavailable', event => {
                if (event.data?.size) chunks.push(event.data);
            });
            recorder.addEventListener('stop', resolve, { once: true });
            recorder.addEventListener('error', event => reject(event.error || new Error('Video encoding failed')), { once: true });
        });

        const drawFrame = () => {
            if (video.readyState >= HTMLMediaElement.HAVE_CURRENT_DATA) {
                context.drawImage(video, 0, 0, outputWidth, outputHeight);
            }
            if (!video.ended && !video.paused) frameRequest = requestAnimationFrame(drawFrame);
        };

        video.currentTime = 0;
        await new Promise(resolve => {
            if (video.currentTime === 0) resolve();
            else video.addEventListener('seeked', resolve, { once: true });
        });
        context.drawImage(video, 0, 0, outputWidth, outputHeight);
        recorder.start(250);

        let timedOut = false;
        let finishPlayback;
        const playbackDone = new Promise(resolve => {
            finishPlayback = resolve;
            video.addEventListener('ended', resolve, { once: true });
            video.addEventListener('error', () => resolve(), { once: true });
        });
        // 实时录制：以视频时长的两倍再加余量作为超时上限，避免异常时永久挂起。
        timeoutId = setTimeout(() => {
            timedOut = true;
            video.pause();
            finishPlayback();
        }, Math.max(30_000, duration * 2000 + 20_000));

        await video.play();
        frameRequest = requestAnimationFrame(drawFrame);
        await playbackDone;
        clearTimeout(timeoutId);
        timeoutId = undefined;
        if (recorder.state !== 'inactive') recorder.stop();
        await recordingDone;
        if (timedOut) return passthrough('timeout');

        const outputType = recorder.mimeType || mimeType;
        const compressedBlob = new Blob(chunks, { type: outputType });
        if (!compressedBlob.size || compressedBlob.size >= file.size * 0.92) {
            return passthrough('no-gain');
        }

        const compressedFile = new File([compressedBlob], getOutputName(file, outputType), {
            type: outputType.split(';')[0],
            lastModified: file.lastModified,
        });
        return {
            file: compressedFile,
            compressed: true,
            reason: 'compressed',
            before: file.size,
            after: compressedFile.size,
        };
    } catch (error) {
        console.warn('Browser video compression failed, using the original file:', error);
        return passthrough('failed');
    } finally {
        if (timeoutId) clearTimeout(timeoutId);
        cancelAnimationFrame(frameRequest);
        video.pause();
        video.removeAttribute('src');
        video.load();
        URL.revokeObjectURL(sourceUrl);
        outputStream?.getTracks().forEach(track => track.stop());
        if (audioContext && audioContext.state !== 'closed') await audioContext.close().catch(() => {});
    }
}
