import {
    LIVE_PHOTO_DEFAULTS,
    clampLivePhotoVideoConfig,
} from '@/utils/upload/livePhotoSettings';
import { compressVideoInBrowser } from '@/utils/upload/browserVideoCompression';

// 不传参数时沿用默认配置（自动压缩、1280 最大边、按 70% 压缩率换算码率），保证其他调用方不受影响。
const DEFAULT_OPTIONS = Object.freeze({
    enabled: LIVE_PHOTO_DEFAULTS.videoCompress,
    rate: LIVE_PHOTO_DEFAULTS.videoRate,
    targetSize: LIVE_PHOTO_DEFAULTS.videoTargetSize,
    maxEdge: LIVE_PHOTO_DEFAULTS.videoMaxEdge,
});

/**
 * 动态照片内嵌视频：与普通视频共用同一套浏览器压缩实现，保持原有的返回结构与单参数调用行为。
 * 独立设置页里的压缩率 / 期望大小 / 最大边长仍然生效。
 */
export async function compressLivePhotoVideo(file, options = DEFAULT_OPTIONS) {
    const settings = clampLivePhotoVideoConfig(options);
    if (!settings.enabled) return { file, compressed: false };

    const result = await compressVideoInBrowser(file, settings);
    return { file: result.file, compressed: result.compressed };
}
